from fractions import Fraction


def guess_value(options_left, right=1, wrong=-1):
    k = options_left
    return Fraction(right) / k + Fraction(wrong) * (k - 1) / k


def net_score(answers, key, right=1, wrong=-1):
    total = 0
    for given, correct in zip(answers, key):
        if given is None:
            continue
        total += right if given == correct else wrong
    return total
